def solve(nums):
    import bisect
    tails=[]
    for x in nums:
        # find insertion point in tails for x
        i=bisect.bisect_left(tails,x)
        # For strictly increasing, we need replace first >= x
        # This maintains minimal tail for each length.
        if i==len(tails):
            tails.append(x)
        else:
            tails[i]=x
    return len(tails)

def solve(matrix):
    if not matrix or not matrix[0]:
        return []
    res = []
    top, bottom = 0, len(matrix)-1
    left, right = 0, len(matrix[0])-1
    while top <= bottom and left <= right:
        # top row
        for c in range(left, right+1):
            res.append(matrix[top][c])
        top += 1
        # right column
        for r in range(top, bottom+1):
            res.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            # bottom row reverse
            for c in range(right, left-1, -1):
                res.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            # left column upward
            for r in range(bottom, top-1, -1):
                res.append(matrix[r][left])
            left += 1
    return res

