def solve(mat):
    # determinant by recursion (Laplace expansion)
    n = len(mat)
    if n == 0:
        return 1
    if n == 1:
        return mat[0][0]
    det = 0
    for j in range(n):
        sub = [row[:j] + row[j+1:] for row in mat[1:]]
        sign = -1 if j % 2 else 1
        det += sign * mat[0][j] * solve(sub)
    return det

