def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Handles any iterable input, works in O(n log n).
    """
    # Convert to list to allow repeated iteration and len check
    arr = list(nums)
    if not arr:
        return 0
    import bisect
    tails = []  # tails[i] = minimum possible tail of an IS of length i+1
    for x in arr:
        # Find insertion point for x in tails (first element >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

