    """Return True if s is a valid IPv4 address.
    Rules: four decimal numbers 0-255, no leading zeros unless the number is exactly '0'.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p or not p.isdigit():
            return False
        # leading zeros not allowed unless the part is exactly '0'
        if len(p) > 1 and p[0] == '0':
            return False
        num = int(p)
        if num < 0 or num > 255:
            return False
    return True

