    """Simplify an absolute Unix path.
    Resolve '.' (current directory) and '..' (parent directory), collapse multiple '/' and remove trailing slash.
    The root is represented as '/'.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    if not stack:
        return '/'
    return '/' + '/'.join(stack)
