{"task_id": "T25", "code": "def solve(matrix):
    # Compute determinant of an integer matrix using Bareiss algorithm for exact integer arithmetic.
    # An empty matrix has determinant 1.
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Copy to avoid mutating input
    A = [list(row) for row in matrix]
    sign = 1
    for k in range(n - 1):
        # Find non‑zero pivot if current is zero
        if A[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update; division is exact
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0
    return sign * A[n - 1][n - 1]
