def solve(weights, values, capacity):
    """0/1 knapsack returning maximum total value fitting within capacity.
    Handles items with zero weight by adding their positive values directly.
    """
    if capacity <= 0:
        return 0
    # Sum values of zero-weight items (only once each)
    extra = 0
    filtered = []  # list of (w, v)
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                extra += v
        else:
            filtered.append((w, v))
    dp = [0] * (capacity + 1)
    for w, v in filtered:
        # iterate backwards to ensure each item used at most once
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity] + extra

