def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Resolve '.' and '..', collapse multiple slashes, and ignore any whitespace around components.
    Returns '/' for the root.
    """
    # Split the path by '/'
    raw_parts = path.split('/')
    stack = []
    for part in raw_parts:
        # Remove surrounding whitespace from each component
        part = part.strip()
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

