def solve(coins, amount):
    # DP for coin change (unbounded). Return min coins or -1.
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array with a sentinel larger than any possible count
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

