def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is a two‑element iterable [start, end]. Meetings where end < start are
    considered invalid and are ignored. A meeting may start exactly when another ends.
    """
    # Filter valid meetings (end >= start)
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        if end < start:
            continue
        valid.append((start, end))
    if not valid:
        return 0
    # Greedy by earliest finishing time
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for start, end in valid:
        if start >= last_end:
            count += 1
            last_end = end
    return count

