    Uses the classic Sieve of Eratosthenes. Handles edge cases for n <= 2 and
    avoids slice‑assignment pitfalls for very small n.
    """
    if n <= 2:
        return 0
    # Initialize boolean list for primality; index i corresponds to number i.
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            # Start marking multiples from p*p to avoid redundant work.
            start = p * p
            for multiple in range(start, n, p):
                is_prime[multiple] = False
    return sum(is_prime)

